環境省は昨日、全国の食品ロスに関する最新調査結果を発表した。それによると、昨年度に国内で発生した食品ロスは約460万トンとなり、前年度と比べて減少したことが分かった。

食品ロスとは、本来食べられるにもかかわらず廃棄される食品を指す。近年、企業や自治体、消費者団体などが削減に向けた取り組みを進めており、その成果が徐々に表れているとみられている。

例えば、スーパーでは賞味期限が近い商品へ値引きシールを貼る取り組みが一般化している。また、飲食店でも食べ残しを減らすために小盛りメニューを導入する事例が増えている。

一方、家庭から発生する食品ロスは依然として大きな割合を占めている。買い過ぎや保存方法の問題によって食品を廃棄してしまうケースが少なくないためだ。

