私はこれまで多くの企業で研修を行ってきましたが、失敗を恐れて行動できない人が少なくありません。もちろん、誰でも失敗はしたくないものです。しかし、失敗を完全に避けようとすると、新しい挑戦そのものを避けるようになってしまいます。

実際、多くの成功事例を調べてみると、その背景には数多くの失敗があります。ところが私たちは成功した結果だけを見てしまい、その過程を見落としがちです。

