例えば、ある政策が成功した理由や失敗した理由を調べることで、人々がどのような課題に直面し、どのような判断をしたのかを知ることができる。また、現在当たり前だと思っている制度や文化も、長い時間をかけて形成されてきたことが分かる。

歴史を学ぶことで、物事を多面的に見る力も養われる。ある出来事であっても、立場によって評価が異なることは少なくない。複数の視点を比較することによって、より深く理解できるのである。

