近年、多くの企業で「1on1ミーティング」が導入されている。1on1ミーティングとは、上司と部下が定期的に1対1で話し合う面談のことである。

従来の面談は評価や業務報告が中心だった。しかし1on1ミーティングでは、日々の悩みや将来の目標、働き方について話し合うことが重視される。

導入した企業からは、「部下が相談しやすくなった」「問題を早期に発見できるようになった」といった声が聞かれる。一方で、「何を話せばよいか分からない」「時間の確保が難しい」といった課題もある。

