その違いはどこにあるのだろうか。

ある研究では、自分で選んだ活動が多い人ほど忙しさによるストレスを感じにくい傾向があるという。反対に、自分の意思とは関係なく決められた予定ばかりの場合、人は強い負担を感じやすい。

