私は社会人3年目です。最近、仕事で後輩を指導する機会が増えました。しかし、自分では丁寧に説明しているつもりなのに、なかなか意図が伝わりません。

そのため同じことを何度も説明することになり、時には「なぜ理解してくれないのだろう」と感じてしまいます。一方で、自分が新人だった頃を思い出すと、先輩の説明を十分理解できていなかったこともありました。

指導する立場として、どのようなことを意識すればよいのでしょうか。

〈回答〉

多くの人が誤解していますが、「説明したこと」と「相手に伝わったこと」は同じではありません。

特に経験の差が大きい場合、自分にとって当たり前の知識が相手には当たり前ではないことがあります。そのため、一度説明しただけで理解されるとは限りません。

また、人によって理解しやすい方法も異なります。口頭説明が分かりやすい人もいれば、図や実例があった方が理解しやすい人もいます。

重要なのは、「なぜ伝わらないのか」を相手の能力だけの問題として考えないことです。説明方法を変えたり、相手へ質問したりしながら理解度を確認することが大切です。

