ある研究では、参加者に90分間連続して作業してもらう場合と、30分ごとに短い休憩を取ってもらう場合を比較した。その結果、後者の方が全体的な作業効率が高い傾向を示した。

研究者は、人間の集中力には限界があり、長時間同じ状態を維持することは難しいと説明している。休憩によって脳が一時的に負荷から解放されることで、その後の集中力回復につながる可能性があるという。

ただし、どのような休憩でも良いわけではない。休憩中に複雑な情報処理を行った場合、十分な回復効果が得られない可能性も指摘されている。

