〈相談〉

私は大学生です。授業やアルバイト、サークル活動などで毎日忙しく過ごしています。しかし、一日の終わりになると「今日は何もできなかった」と感じることがあります。

実際には予定をこなしているはずなのに、達成感がありません。周囲の友人を見ると、資格取得や語学学習などにも取り組んでいて、自分だけが成長していないように思えてしまいます。

もっと充実した毎日を送るにはどうすればよいでしょうか。

〈回答〉

まず確認したいのは、「充実している状態」をどのように定義しているかということです。

多くの人は、自分の現状ではなく他人との比較によって満足度を判断してしまいます。しかし他人の成果だけを見ていると、自分が既に達成したことを見落としてしまうことがあります。

また、成長とは資格取得や目に見える成果だけを意味するものではありません。人との関わりや経験から得られる学びも重要です。

もちろん目標を持つことは大切です。しかし、今できていることを適切に評価しなければ、常に不足感だけが残ってしまうでしょう。

