私たちは毎日、多くの情報に囲まれて生活しています。新聞、テレビ、インターネット、SNSなど、情報源は以前よりもはるかに増えました。その結果、必要な情報へ簡単にアクセスできるようになった一方で、誤った情報へ触れる機会も増えています。

例えば、ある出来事について調べると、正反対の意見が見つかることがあります。その時、「どちらが正しいのか」と悩む人も少なくありません。しかし重要なのは、すぐに結論を出すことではなく、複数の情報源を確認することです。

また、人は自分の考えに近い情報ばかりを集める傾向があります。これを心理学では「確証バイアス」と呼びます。この傾向が強いと、自分と異なる意見を十分に検討しなくなる可能性があります。

もちろん全ての情報を疑い続ける必要はありません。しかし、情報をそのまま受け入れるのではなく、「なぜそう言えるのか」を考える習慣は大切です。

